import React, { useState, useEffect } from 'react';
import { getAllExamCounts } from '../services/api';  // Import the getAllExamCounts function

const ExamDataCount = ({ franchiseId }) => {
    const [examDataCount, setExamDataCount] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    // Function to fetch exam data count using getAllExamCounts
    const fetchExamDataCount = async () => {
        setLoading(true);
        setError('');
        try {
            const response = await getAllExamCounts(franchiseId);
            setExamDataCount(response);  // Assuming the response is the data containing the counts
        } catch (err) {
            console.error(err);
            setError('An error occurred while fetching data.');
        } finally {
            setLoading(false);
        }
    };

    // Fetch data on component mount
    useEffect(() => {
        fetchExamDataCount();
    }, [franchiseId]);

    return (
        <div>
            <h2>Exam Data Count for Franchise {franchiseId}</h2>

            <button onClick={fetchExamDataCount} disabled={loading}>
                {loading ? 'Loading...' : 'Refresh Exam Data Count'}
            </button>

            {error && <p style={{ color: 'red' }}>{error}</p>}

            {examDataCount !== null && !loading && (
                <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '20px', gap: '10px', flexWrap: 'wrap' }}>
                    {/* Box for Exams Today */}
                    <div style={{
                        width: '28%', 
                        padding: '12px', 
                        border: '1px solid #ccc', 
                        borderRadius: '8px', 
                        textAlign: 'center', 
                        backgroundColor: '#f1f1f1',
                        boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)',
                    }}>
                        <h3 style={{ color: '#333', fontSize: '16px' }}>Today</h3>
                        <p style={{ color: '#555', fontSize: '18px' }}>
                            {examDataCount.examsByDay !== undefined ? examDataCount.examsByDay : 'No data'}
                        </p>
                    </div>

                    {/* Box for Exams This Week */}
                    <div style={{
                        width: '28%', 
                        padding: '12px', 
                        border: '1px solid #ccc', 
                        borderRadius: '8px', 
                        textAlign: 'center', 
                        backgroundColor: '#e0f7fa',
                        boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)',
                    }}>
                        <h3 style={{ color: '#00796b', fontSize: '16px' }}>Week</h3>
                        <p style={{ color: '#004d40', fontSize: '18px' }}>
                            {examDataCount.examsByWeek !== undefined ? examDataCount.examsByWeek : 'No data'}
                        </p>
                    </div>

                    {/* Box for Exams This Month */}
                    <div style={{
                        width: '28%', 
                        padding: '12px', 
                        border: '1px solid #ccc', 
                        borderRadius: '8px', 
                        textAlign: 'center', 
                        backgroundColor: '#fff3e0',
                        boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)',
                    }}>
                        <h3 style={{ color: '#f57c00', fontSize: '16px' }}>Month</h3>
                        <p style={{ color: '#e65100', fontSize: '18px' }}>
                            {examDataCount.examsByMonth !== undefined ? examDataCount.examsByMonth : 'No data'}
                        </p>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ExamDataCount;
